{"command":"cat <<'EOF' > solver_exact_cover.py
import itertools
from typing import List, Dict
from problems import ExactCover

def is_exact_cover(instance: Dict) -> bool:
    ExactCover.validate(instance)
    u = instance["universe_size"]
    sets: List[List[int]] = instance["sets"]
    n_sets = len(sets)
    # iterate over all subsets of sets (up to 2^n_sets)
    for r in range(n_sets + 1):
        for combo in itertools.combinations(range(n_sets), r):
            covered = [0] * u
            ok = True
            for idx in combo:
                for e in sets[idx]:
                    covered[e] += 1
                    if covered[e] > 1:
                        ok = False
                        break
                if not ok:
                    break
            if ok and all(c == 1 for c in covered):
                return True
    return False
EOF"}

